; Generated by tests/x87_round_scale_tests.py: FRNDINT in every rounding mode: halves, carries into the next power of two, 64-bit operands below 2^53, zeros, infinities, NaNs, denormals, PE and IE unmasked.
; Expected results and status words from exact integer arithmetic
; (see the script). Each case: FNINIT, FLDCW, FLD ST1, FLD ST0 (m80),
; the operation, FNSTSW (all but B checked), FNCLEX, then ST0 and ST1
; stored and compared (an unmasked exception leaves ST0 unwritten).
; Fail code (port E4): case index + 1 in the low word, the status word
; in the high word; then the value stored last.

BITS 16
org 0

STATUS_PORT equ 0xE0
DATA_PORT   equ 0xE4

start:
    cli
    mov ax, cs
    mov ds, ax
    mov es, ax
    mov ss, ax
    mov sp, 0xfff0
    cld
    mov si, cases
    xor bp, bp
next:
    cmp bp, 556
    je pass
    fninit
    fldcw [si + 2]
    fld tword [si + 4]
    fld tword [si + 14]
    mov al, [si]
    cmp al, 1
    je .fscale
    cmp al, 2
    je .fprem
    cmp al, 3
    je .fprem1
    frndint
    jmp .done
.fscale:
    fscale
    jmp .done
.fprem:
    fprem
    jmp .done
.fprem1:
    fprem1
.done:
    fnstsw ax
    mov [status], ax
    fnclex
    and ax, 0x7fff
    cmp ax, [si + 34]
    jne fail
    fstp tword [result]
    lea di, [si + 24]
    call compare
    jne fail
    fstp tword [result]
    lea di, [si + 4]
    call compare
    jne fail
    add si, 36
    inc bp
    jmp next
compare:
    push si
    mov si, result
    mov cx, 5
    repe cmpsw
    pop si
    ret
pass:
    mov al, 1
    out STATUS_PORT, al
    hlt
fail:
    mov ax, [status]
    shl eax, 16
    mov ax, bp
    inc ax
    out DATA_PORT, eax
    mov eax, [result]
    out DATA_PORT, eax
    mov eax, [result + 4]
    out DATA_PORT, eax
    mov ax, [result + 8]
    out DATA_PORT, ax
    mov al, 0xff
    out STATUS_PORT, al
    hlt

align 2
status: dw 0
result: times 10 db 0
align 2
